def _is_binary(path: Path) -> bool:
    return path.suffix.lower() in _BINARY_EXTENSIONS


def _tracked_files_in_scope(scope: _Scope) -> list[str]:
    result = subprocess.run(
        ["git", "ls-files"],
        cwd=scope.root,
        capture_output=True,
        encoding="utf-8",
        check=True,
    )
    in_scope = []
    for line in result.stdout.splitlines():
        rel = line.strip()
        if not rel:
            continue
        posix_rel = rel.replace("\\", "/")
        if posix_rel in scope.exclude_files:
            continue
        if any(posix_rel.startswith(p) for p in scope.exclude_dir_prefixes):
            continue
        full = scope.root / rel
        if not full.is_file():
            continue
        if _is_binary(full):
            continue
        in_scope.append(posix_rel)
    return in_scope


def _string_has_h_dot_below(s: str) -> bool:
    """True if `s` contains h-with-dot-below specifically (precomposed U+1E25/U+1E24,
    or decomposed "h"/"H" + U+0323) -- NOT just any U+0323, since U+0323 also
    legitimately appears on other base letters (e.g. "S" in "Sere", "t" in
    "qetannah"), which is a different character combination and out of scope."""
    if _H_WITH_DOT_BELOW in s or _H_CAP_WITH_DOT_BELOW in s:
        return True
    for i, ch in enumerate(s):
        if ch in ("h", "H") and i + 1 < len(s) and s[i + 1] == _COMBINING_DOT_BELOW:
            return True
    return False


# --- General NFC-Latin-diacritic enforcement (generalizes the het NFC rule to
# --- every Latin base letter carrying a combining diacritic that has a
# --- precomposed form). Composes conceptually only Latin-script clusters; every
# --- Hebrew codepoint (U+0590-05FF, U+FB1D-FB4F) is left untouched. Self-
# --- contained (stdlib unicodedata only), no literal combining mark is typed.
_HEBREW_RANGES_NFC = ((0x0590, 0x05FF), (0xFB1D, 0xFB4F))


def _is_hebrew_cp(ch):
    o = ord(ch)
    return any(lo <= o <= hi for lo, hi in _HEBREW_RANGES_NFC)


def _is_latin_base(ch):
    if unicodedata.combining(ch) != 0:
        return False
    try:
        return unicodedata.name(ch).startswith("LATIN")
    except ValueError:
        return False


def _find_decomposed_latin_clusters(text):
    """Return sorted 1-indexed line numbers where a Latin base + combining
    mark(s) has a strictly-shorter NFC (precomposed) form -- hand-authored
    source that should be composed. Hebrew clusters are never flagged."""
    line_nos = set()
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if _is_latin_base(ch) and i + 1 < n and unicodedata.combining(text[i + 1]) != 0:
            j = i + 1
            while (
                j < n
                and unicodedata.combining(text[j]) != 0
                and not _is_hebrew_cp(text[j])
            ):
                j += 1
            cluster = text[i:j]
            nfc = unicodedata.normalize("NFC", cluster)
            if len(nfc) < len(cluster) and not any(_is_hebrew_cp(c) for c in nfc):
                line_nos.add(text.count("\n", 0, i) + 1)
            i = j
            continue
        i += 1
    return sorted(line_nos)


class TestHDotBelowNfc(unittest.TestCase):
    """Hand-authored source in both repos must use precomposed h-with-dot-below,
    never the decomposed sequence, and must never use either Unicode form in a
    real comment (plain ASCII "x"/"X" instead)."""

    @classmethod
    def setUpClass(cls):
        cls.scopes = _scopes()
        cls.in_scope_files = {
            scope.label: _tracked_files_in_scope(scope) for scope in cls.scopes
        }
        # Sanity check: the scoping logic should select a non-trivial number of
        # files per repo (catches a badly broken exclusion filter that
        # accidentally excludes everything).
        for scope in cls.scopes:
            found = len(cls.in_scope_files[scope.label])
            assert found > scope.floor, (
                f"Only {found} {scope.label} files in scope (floor {scope.floor}) -- "
                "exclusion filters may be too broad."
            )

    def _each_file(self):
        """Yield (label, posix_rel, full_path) across every scope."""
        for scope in self.scopes:
            for posix_rel in self.in_scope_files[scope.label]:
                yield scope.label, posix_rel, scope.root / posix_rel

    def test_no_decomposed_h_dot_below_in_hand_authored_files(self):
        offenders = []
        for label, posix_rel, full in self._each_file():
            text = full.read_text(encoding="utf-8")
            for i, ch in enumerate(text):
                if (
                    ch in ("h", "H")
                    and i + 1 < len(text)
                    and text[i + 1] == _COMBINING_DOT_BELOW
                ):
                    line_no = text.count("\n", 0, i) + 1
                    offenders.append(f"{label}/{posix_rel}:{line_no}")
                    break
        self.assertEqual(
            offenders,
            [],
            "Found decomposed h-with-dot-below (h/H + COMBINING DOT BELOW) "
            "in hand-authored files; run the NFC migration or fix by hand: "
            f"{offenders}",
        )

    def test_no_decomposed_latin_diacritic_cluster(self):
        """General NFC rule (supersedes the het-only file check above): no
        hand-authored file may contain a decomposed Latin base+diacritic that
        has a precomposed NFC form (e.g. t/s + dot-below, a + breve, i +
        acute, a + diaeresis). Applies to literals AND comments alike -- this
        is pure NFC precomposition and never ASCII-fies anything; the
        het->ASCII 'x' comment rule is a separate assertion below."""
        offenders = []
        for label, posix_rel, full in self._each_file():
            text = full.read_text(encoding="utf-8")
            for line_no in _find_decomposed_latin_clusters(text):
                offenders.append(f"{label}/{posix_rel}:{line_no}")
        self.assertEqual(
            offenders,
            [],
            "Found decomposed Latin base+diacritic clusters that have a "
            "precomposed NFC form; run the NFC-Latin migration: "
            f"{offenders}",
        )

    def test_comments_use_ascii_not_h_dot_below(self):
        """Real Python comments (tokenize COMMENT tokens) must not carry either
        Unicode het form. Uses tokenize, not line.find('#'), because the wlc code
        embeds '#' inside string literals (the '@...#' WLC markup), where het is
        a legitimate output-facing value, not a comment."""
        offenders = []
        for label, posix_rel, full in self._each_file():
            if not posix_rel.endswith(".py"):
                continue
            if posix_rel in _COMMENT_GLYPH_ALLOWLIST:
                continue
            text = full.read_text(encoding="utf-8")
            try:
                tokens = tokenize.generate_tokens(io.StringIO(text).readline)
                for tok in tokens:
                    if tok.type == tokenize.COMMENT and _string_has_h_dot_below(
                        tok.string
                    ):
                        offenders.append(f"{label}/{posix_rel}:{tok.start[0]}")
            except (tokenize.TokenError, IndentationError, SyntaxError):
                # Malformed/partial source: fall back to a naive '#' scan so we
                # never silently skip a file. Rare; keeps coverage conservative.
                for line_no, line in enumerate(text.split("\n"), start=1):
                    hash_idx = line.find("#")
                    if hash_idx != -1 and _string_has_h_dot_below(line[hash_idx:]):
                        offenders.append(f"{label}/{posix_rel}:{line_no}")
        self.assertEqual(
            offenders,
            [],
            "Found h-with-dot-below (either Unicode form) in a comment; "
            f"use plain ASCII x/X instead: {offenders}",
        )

    def test_h_dot_below_composition_is_canonically_lossless(self):
        """Spot-check unicodedata agrees h/H + U+0323 composes to
        U+1E25/U+1E24, guarding the core assumption behind this test and
        the migration script that produced the current state."""
        self.assertEqual(
            unicodedata.normalize("NFC", "h" + _COMBINING_DOT_BELOW),
            _H_WITH_DOT_BELOW,
        )
        self.assertEqual(
            unicodedata.normalize("NFC", "H" + _COMBINING_DOT_BELOW),
            _H_CAP_WITH_DOT_BELOW,
        )

    def test_detector_flags_decomposed_and_precomposed_h_dot_below(self):
        self.assertTrue(
            _string_has_h_dot_below("guttural / h" + _COMBINING_DOT_BELOW + " slot")
        )
        self.assertTrue(
            _string_has_h_dot_below("guttural / " + _H_WITH_DOT_BELOW + " slot")
        )
        self.assertTrue(
            _string_has_h_dot_below("Capital H" + _COMBINING_DOT_BELOW + "olam")
        )
        self.assertTrue(
            _string_has_h_dot_below("Capital " + _H_CAP_WITH_DOT_BELOW + "olam")
        )

    def test_detector_ignores_dot_below_on_other_base_letters(self):
        # U+0323 legitimately appears on letters other than h/H (e.g. "S" in
        # "Sere", "t" in "qetannah"); that is a different combination and must
        # NOT be flagged.
        self.assertFalse(
            _string_has_h_dot_below("Closed, S" + _COMBINING_DOT_BELOW + "ere-vowelled")
        )
        self.assertFalse(
            _string_has_h_dot_below("shalshelet qet" + _COMBINING_DOT_BELOW + "annah")
        )


if __name__ == "__main__":
    unittest.main()
